## Why This Is Asked
Tests cross-language async design, memory ownership, and error propagation in CGO.

## Key Concepts
- CGO callbacks from C to Go and lifetime guarantees
- Correctly freeing C-allocated strings from Go
- Streaming results via channels with backpressure and cancellation
- Robust error propagation across language boundaries

## Code Example
```c
// header: cgob_blocks.h
void process_blocks_async(const void** blocks, const size_t* lengths, size_t n, void(*cb)(size_t idx, const char* json, void* user), void* user);
```
```go
// binding.go
package main

/*
#include "cgob_blocks.h"
#include <stdlib.h>

typedef struct {
    size_t idx;
    const char* json;
} CallbackData;

extern void goCallback(size_t idx, const char* json, void* user);

static void cgo_callback_wrapper(size_t idx, const char* json, void* user) {
    goCallback(idx, json, user);
}

static void process_blocks_wrapper(const void** blocks, const size_t* lengths, size_t n, void* user) {
    process_blocks_async(blocks, lengths, n, cgo_callback_wrapper, user);
}
*/
import "C"
import (
    "context"
    "sync"
    "unsafe"
)

type result struct {
    idx  int
       json string
    err  error
}

func DispatchBlocks(blocks [][]byte) (<-chan string, error) {
    if len(blocks) == 0 {
        return nil, nil
    }

    n := len(blocks)
    cBlocks := make([]*C.void, n)
    cLengths := make([]C.size_t, n)

    for i, block := range blocks {
        if len(block) > 0 {
            cBlocks[i] = unsafe.Pointer(&block[0])
        }
        cLengths[i] = C.size_t(len(block))
    }

    ctx, cancel := context.WithCancel(context.Background())
    results := make(chan string, n)
    errCh := make(chan error, 1)

    var wg sync.WaitGroup
    wg.Add(1)

    go func() {
        defer wg.Done()
        defer close(results)

        C.process_blocks_wrapper(
            &cBlocks[0],
            &cLengths[0],
            C.size_t(n),
            unsafe.Pointer(&resultCtx{ctx: ctx, results: results, cancel: cancel}),
        )
    }()

    go func() {
        wg.Wait()
        close(errCh)
    }()

    return results, nil
}

type resultCtx struct {
    ctx    context.Context
    results chan<- string
    cancel context.CancelFunc
}

//export goCallback
func goCallback(idx C.size_t, json *C.char, user unsafe.Pointer) {
    ctxPtr := (*resultCtx)(user)

    if ctxPtr.ctx.Err() != nil {
        return
    }

    if json == nil {
        return
    }

    result := C.GoString(json)
    C.free(unsafe.Pointer(json))

    select {
    case ctxPtr.results <- result:
    case <-ctxPtr.ctx.Done():
        ctxPtr.cancel()
    }
}
```

## Key Design Decisions

1. **Pointer Handling**: Blocks are passed as array of pointers with their lengths, maintaining zero-copy semantics from Go to C

2. **Memory Ownership**: C-allocated JSON strings are freed via C.free after converting to Go string, ensuring no memory leaks

3. **Cancellation**: Context cancellation enables early termination; callback checks ctx.Err() before sending

4. **Backpressure**: Buffered channel (size n) prevents unbounded memory growth

5. **Thread Safety**: sync.WaitGroup ensures proper cleanup before function return

## Why This Is Asked
Tests memory ownership across the CGO boundary and safe deallocation. Tokenization is simple in C but memory mgmt is error-prone; the Go binding must copy results and free C memory in all paths, including errors. Running two tokenizations concurrently checks thread safety of the wrapper.

## Key Concepts
- CGO memory ownership and malloc/free
- Converting C arrays of strings to Go slices
- Error propagation and nil checks
- Concurrency safety with CGO calls

## Code Example
```c
// header (tokenize.h)
char** tokenize(const char* input, size_t* count);
```

```c
// minimal implementation (tokenize.c)
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

char** tokenize(const char* input, size_t* count) {
  if (!input) { *count = 0; return NULL; }
  // simple two-pass: count tokens
  size_t n = 0; const char* p = input; while (*p) { while (isspace((unsigned char)*p)) p++; if (*p) { n++; while (*p && !isspace((unsigned char)*p)) p++; } }
  char** tokens = (char**)malloc(n * sizeof(char*));
  if (!tokens) { *count = 0; return NULL; }
  size_t idx = 0; p = input; while (*p) {
    while (*p && isspace((unsigned char)*p)) p++;
    if (!*p) break;
    const char* start = p; while (*p && !isspace((unsigned char)*p)) p++;
    size_t len = p - start;
    tokens[idx] = (char*)malloc(len + 1);
    memcpy(tokens[idx], start, len);
    tokens[idx][len] = '\0';
    idx++;
  }
  *count = idx;
  return tokens;
}
```

```go
// Go binding sketch (tokenize.go)
package main

/*
#include <stdlib.h>
#include "tokenize.h"
*/
import "C"
import (
  "errors"
  "unsafe"
)

func Tokenize(text string) ([]string, error) {
  cstr := C.CString(text)
  defer C.free(unsafe.Pointer(cstr))
  var count C.size_t
  tokens := C.tokenize(cstr, &count)
  if tokens == nil {
    return nil, errors.New("tokenize failed")
  }
  // copy to Go and free C memory
  result := make([]string, int(count))
  for i := 0; i < int(count); i++ {
    s := C.GoString(tokens[i])
    result[i] = s
    C.free(unsafe.Pointer(tokens[i]))
  }
  C.free(unsafe.Pointer(tokens))
  return result, nil
}
```

```go
// concurrent usage (main.go)
package main
import (
  "fmt"
  "sync"
)

func main() {
  var wg sync.WaitGroup
  inputs := []string{"hello world from CGO", "Go + C interop"}
  for _, s := range inputs {
    wg.Add(1)
    go func(text string) {
      defer wg.Done()
      out, err := Tokenize(text)
      if err != nil { fmt.Println("err:", err); return }
      fmt.Println(out)
    }(s)
  }
  wg.Wait()
}
```

